#include<stdio.h>

#include<math.h>

bool flag[1000000];

int main(void)

{

	long long i,j,p,n,count;

	p = (long long)sqrt(1000000.0);

	for(i = 3; i <= p; i = i + 2)

	{

		if(flag[i] == false)

		{

			for(j = i * i; j <= 1000000; j = j + 2 * i)

			{

				flag[j] = true;



			}

		}

	}



	while((scanf("%lld",&n)) != EOF)

	{



		if(n == 1 || n == 0)

			count = 0;

		else

		{

			count = 1;

			for(i = 3; i <= n; i = i + 2)

			{

				if(flag[i] == false)

					count++;

			}

		}

		printf("%lld
",count);

	}







	return 0;

}

#include<iostream>

#include<algorithm>

using namespace std;



int main(){

  int n;

  int a[5000];

  int tmp;

  int ans;



  while(1){

    cin >> n;

    if(!n)break;



    for(int i=0;i<n;i++){

      cin >> a[i];

    }



    ans = a[0];

    for(int i=0;i<n;i++){

      for(int j=i;j<n;j++){

	if(i==j)tmp = a[i];

	else tmp += a[j];

	ans = max(tmp,ans);

      }

    }



    cout << ans << endl;

  }

}

#include"stdc++.h"

using namespace std;



int a[20];



bool check(int x)

{

	int pre = 0;

	for (int i = 0; i < 10; i++) if (x & (1 << i))

	{

		if (a[i] < pre) return false;

		pre = a[i];

	}

	return true;

}



bool dfs(int i, int x, int pre)

{

	if (i == 10)

	{

		return check(x);

	}

	bool temp = false;

	if (a[i] > pre) temp = dfs(i + 1, x, a[i]);

	return temp || dfs(i + 1, x | (1 << i), pre);

}



int main()

{

	int T;

	cin >> T;

	while (T--)

	{

		for (int i = 0; i < 10; i++) scanf("%d", &a[i]);

		printf("%s
", dfs(1, 0, a[0]) ? "YES" : "NO");

	}

	return 0;

}

#include <iostream>   

#include <map>   

#include <sstream>   

#include <string.h>   

using namespace std;   



map<int, char> AlphabetTable;   

map<int, int> table;   



char decode(char a){   



    int z = a - 'a';   



    for(int i = 0; i < 26; i++){   

        if(table[i] == z) return AlphabetTable[i];   

    }   

}   



void makeTable(int a, int b){   

    for(int i = 0; i < 26; i++){   

        table[i] = (a*i+b) % 26;   

    }   

}   



void makeAlphabetTable(){   



    char c = 'a';   



    for(int i = 0; i < 26; i++){   

        AlphabetTable[i] = c;   

        c++;   

    }   

}   



int main(){   



    string code, tmp;   

    int n;   



    getline (cin, code);   

    stringstream ssn(code);   

    ssn >> n;   

    makeAlphabetTable();   

    for(int i = 0; i < n; i++){   

        getline(cin, code );   

        tmp = code;   

        for(int b = 0; b < 26; b++){   

            for(int a = 1; a < 26; a+=2){   

                if(a%13 != 0){   

                    makeTable(a, b);   

                    code = tmp;   

                    for(int j = 0; j < code.length(); j++){   

                        if('a' <= code[j] && code[j] <= 'z'){   

                            code[j] = decode(code[j]);   

                        }   

                    }   

                    if(code.find("this") != -1 || code.find("that")!= -1){   

                        cout << code << endl;   

                        break;   

                    }   

                }   

            }   

        }   

    }   



    return 0;   

}
